enum L10n {
    static func locale(_ language:String)->Locale { language == "system" ? .current : Locale(identifier:language) }
    static func text(_ key:String,language:String)->String {
        let code=locale(language).language.languageCode?.identifier ?? "en"
        let index=code == "pt" ? 1 : code == "es" ? 2 : 0
        return strings[key]?[index] ?? diagnostics[key]?[index] ?? key
    }
