    static let diagnostics:[String:[String]]=[
        "Cópias rastreadas não localizadas. Gravação manual e automática bloqueada até reconciliar as identidades.":["Tracked copies could not be located. Manual and automatic writes are blocked until identities are reconciled.","Cópias rastreadas não localizadas. Gravação manual e automática bloqueada até reconciliar as identidades.","No se localizaron copias registradas. Escritura manual y automática bloqueada hasta reconciliar las identidades."],
        "Esta rota não possui autorização automática válida.":["This route has no valid automatic sync authorization.", "Esta rota não possui autorização automática válida.", "Esta ruta no tiene una autorización válida para la sincronización automática."],
        "Há cópias rastreadas não localizadas. Sincronização automática suspensa para evitar duplicatas.":["Some tracked copies could not be located. Automatic sync is suspended to prevent duplicates.", "Há cópias rastreadas não localizadas. Sincronização automática suspensa para evitar duplicatas.", "No se han podido localizar algunas copias rastreadas. La sincronización automática está suspendida para evitar duplicados."],
        "Há identidades não localizadas. Limpeza bloqueada até revisão.":["Some identities could not be located. Cleanup is blocked pending review.", "Há identidades não localizadas. Limpeza bloqueada até revisão.", "No se han podido localizar algunas identidades. La limpieza está bloqueada hasta que se revisen."],
        "Origem ambígua. Nenhuma limpeza proposta.":["Ambiguous source. No cleanup proposed.", "Origem ambígua. Nenhuma limpeza proposta.", "Origen ambiguo. No se propone ninguna limpieza."],
        "Tentativa anterior não reconciliada. Repetição bloqueada.":["Previous attempt has not been reconciled. Retrying is blocked.", "Tentativa anterior não reconciliada. Repetição bloqueada.", "El intento anterior no se ha conciliado. Está bloqueado volver a intentarlo."],
        "Tentativa de gravação não corresponde ao registro persistido.":["Write attempt does not match the persisted record.", "Tentativa de gravação não corresponde ao registro persistido.", "El intento de escritura no coincide con el registro guardado."],
        "Não foi possível abrir o controle de instância do aplicativo.":["Could not open the app's instance control.", "Não foi possível abrir o controle de instância do aplicativo.", "No se pudo abrir el control de instancias de la aplicación."],
        "Outra instância do WorkHarbor já está usando estes dados.":["Another instance of WorkHarbor is already using this data.", "Outra instância do WorkHarbor já está usando estes dados.", "Otra instancia de WorkHarbor ya está usando estos datos."],
        "Escolha origem existente e destino diferente, gravável; buffers entre 0 e 240 minutos.":["Choose an existing source and a different, writable destination; buffers must be between 0 and 240 minutes.", "Escolha origem existente e destino diferente, gravável; buffers entre 0 e 240 minutos.", "Elige un origen existente y un destino diferente con permiso de escritura; los márgenes deben estar entre 0 y 240 minutos."],
        "Leitura incompleta. Nenhuma alteração será proposta.":["Incomplete read. No changes will be proposed.", "Leitura incompleta. Nenhuma alteração será proposta.", "Lectura incompleta. No se propondrá ningún cambio."],
