        "Identidade ambígua de ocorrência. Prévia bloqueada.":["Ambiguous occurrence identity. Preview blocked.", "Identidade ambígua de ocorrência. Prévia bloqueada.", "Identidad de ocurrencia ambigua. Vista previa bloqueada."],
        "Evento com intervalo inválido.":["Event has an invalid time range.", "Evento com intervalo inválido.", "El evento tiene un intervalo de tiempo no válido."],
        "Prévia sintética ou sem confirmação: gravação bloqueada.":["Synthetic or unconfirmed preview: writing blocked.", "Prévia sintética ou sem confirmação: gravação bloqueada.", "Vista previa sintética o sin confirmar: escritura bloqueada."],
